	 (6,'โครงการ "สามบุรีอาภรณ์สยาม สืบสาน ภูมิปัญญา อัตลักษณ์ผ้าทอ สู่ชุดไทยพระราชนิยมเพื่อขับเคลื่อน Soft Power"','โครงการ-สามบรอาภรณสยาม-สบสาน-ภมปญญา-อตลกษณผาทอ-สชดไทยพระราชนยมเพอขบเคลอน-soft-power','THREE_BURI_LEARNING_RESOURCES','<p>โครงการ "สามบุรีอาภรณ์สยาม สืบสาน ภูมิปัญญา อัตลักษณ์ผ้าทอ สู่ชุดไทยพระราชนิยมเพื่อขับเคลื่อน Soft Power"</p>','contents/covers/SO8ulb9LkUB3MQe64tQJpvaKG2gMddSfIp5wYcMl.png',NULL,'https://www.youtube.com/watch?v=wAV4NK82few',1,0,0,NULL,NULL,1,1,'2026-07-29 10:38:00','2026-07-31 04:39:42','2026-08-01 07:20:16',NULL),
	 (6,'โครงการพัฒนาอัตลักษณ์ศิลปวัฒนธรรมท้องถิ่นในรูปแบบ Soft Power (Food)','โครงการพฒนาอตลกษณศลปวฒนธรรมทองถนในรปแบบ-soft-power-food','THREE_BURI_LEARNING_RESOURCES','<p>โครงการพัฒนาอัตลักษณ์ศิลปวัฒนธรรมท้องถิ่นในรูปแบบ Soft Power (Food) "สำรับกับข้าว 3 บุรี" (สำรับเทพสตรี : อาหารลพบุรีในมิติ Soft Power)</p>','contents/covers/KXonMpRzXuWElKLUHsvVjMyaGiVIclAzrZQkB6o7.png','doc_1785473912_6a6c2b78893a7.pdf','https://www.youtube.com/watch?v=rWPUSHVM4ag',2,2,2,NULL,NULL,1,1,'2026-07-29 10:38:00','2026-07-31 04:40:21','2026-08-01 13:14:07',NULL),
	 (2,'การประชุมคณะกรรมการประจำสำนักศิลปะและวัฒนธรรม','การประชมคณะกรรมการประจำสำนกศลปะและวฒนธรรม','PROJECTS_AND_ACTIVITIES','<p>การประชุมคณะกรรมการประจำสำนักศิลปะและวัฒนธรรม</p>','contents/covers/rOLMP9D63qC76D5eEUstXEZc79ZzuQ3oqWNLRd5q.jpg',NULL,NULL,0,0,0,NULL,NULL,1,1,'2026-07-29 11:45:00','2026-07-31 04:45:41','2026-07-31 04:45:41',NULL),
	 (2,'พิธีถวายพานพุ่มทอง-พานพุ่มเงิน และพิธีจุดเทียนถวายพระพรชัยมงคล เนื่องในโอกาสวันเฉลิมพระชนมพรรษา สมเด็จพระนางเจ้าสุทิดา พัชรสุธาพิมลลักษณ พระบรมราชินี วันที่ 3 มิถุนายน พ.ศ. 2568','พธถวายพานพมทอง-พานพมเงน-และพธจดเทยนถวายพระพรชยมงคล-เนองในโอกาสวนเฉลมพระชนมพรรษา-สมเดจพระนางเจาสทดา-พชรสธาพมลลกษณ-พระบรมราชน-วนท-3-มถนายน-พศ-2568','PROJECTS_AND_ACTIVITIES','<p>เมื่อวันที่ 3 มิถุนายน พ.ศ. 2568 ณ หอประชุม 1 ผศ.ดร.กันยา บาร์นท์ อธิการบดีมหาวิทยาลัยราชภัฏเทพสตรี นำคณะผู้บริหาร คณาจารย์ บุคลากร และนักศึกษามหาวิทยาลัยราชภัฏเทพสตรี ร่วมพิธีถวายเครื่องราชสักการะ พิธีถวายพานพุ่มทอง-พานพุ่มเงิน และพิธีจุดเทียนถวายพระพรชัยมงคล เนื่องในโอกาสวันเฉลิมพระชนมพรรษา สมเด็จพระนางเจ้าสุทิดา พัชรสุธาพิมลลักษณ พระบรมราชินี วันที่ 3 มิถุนายน พ.ศ. 2568 เพื่อเป็นการแสดงความจงรักภักดีและน้อมสำนึกในพระมหากรุณาธิคุณของสมเด็จพระนางเจ้าฯ พระบรมราชินี ซึ่งจัดโดยกองพัฒนานักศึกษา สำนักงานอธิการบดี ร่วมกับสภานักศึกษา ภาคปกติ และองค์การบริหารนักศึกษา ภาคปกติ</p><p>ขอบคุณข่าวและภาพข่าวจากงานประชาสัมพันธ์</p>','contents/covers/OdgGLdO4yHcDxI8UdUjMjH5TsDHdSTuwiobb5enD.jpg',NULL,NULL,1,0,0,NULL,NULL,1,1,'2026-07-31 04:46:44','2026-07-31 04:46:44','2026-08-01 10:31:12',NULL);
INSERT INTO enterprise_cms.contents (category_id,title,slug,`type`,body,cover_image,secure_pdf_path,youtube_url,view_count,download_count,share_count,meta_title,meta_description,user_id,is_active,published_at,created_at,updated_at,deleted_at) VALUES
	 (2,'พิธีวางพวงมาลาถวายราชสักการะเนื่องในวันที่ระลึกพระบาทสมเด็จพระปกเกล้าเจ้าอยู่หัว  รัชกาลที่ 7','พธวางพวงมาลาถวายราชสกการะเนองในวนทระลกพระบาทสมเดจพระปกเกลาเจาอยหว-รชกาลท-7','NEWS','<h1>อาจารย์ณฤทธิ์ ประจงแต่ง</h1><p>ผู้อำนวยการสำนักศิลปะและวัฒนธรรม <a href="https://www.facebook.com/profile.php?id=61556669979693&amp;__cft__[0]=AZV2vF0x3xmCeXTCuVlO_KigB9oHCm40j2TJvMWW1NSbXzimG1fU669JgGdbCqOmet_M9i7BRFzy5CGe15tdKBY0XmLo2lhTtu_9BkzyKXadRjjQzwJAodzoJM4_bwkg3pRMjYq0HtnNQ7rI7BeiDX-OZk3M9S66KdRYPcFSWIV62w6T5Cu0DrlMDOMBP_OgHIPpvZ18Xf2gvzT-X-y4OQiBGJ7oE6BUpW_sUSu5CD34Ug&amp;__tn__=-]K-y-R">มหาวิทยาลัยราชภัฏเทพสตรี</a> ได้รับมอบหมายจากท่านอธิการบดี เข้าร่วมพิธีวันที่ระลึกพระบาทสมเด็จพระปกเกล้าเจ้าอยู่หัว</p><p>วันที่ 30 พฤษภาคม 2568 เวลา 08.30 น. ที่ หอประชุมอำเภอเมืองลพบุรี นายอำพล อังคภากรณ์กุล ผู้ว่าราชการจังหวัดลพบุรี เป็นประธานในพิธีวางพวงมาลาถวายราชสักการะเนื่องในวันที่ระลึกพระบาทสมเด็จพระปกเกล้าเจ้าอยู่หัว รัชกาลที่ 7 โดยมีนางสุวจี ศิริปัญโญ นายกเหล่ากาชาดจังหวัดลพบุรี ข้าราชการ ตุลาการ ทหาร ตำรวจ พสกนิกรทุกหมู่เหล่า เข้าร่วมพิธี</p><p>พระบาทสมเด็จพระปกเกล้าเจ้าอยู่หัว รัชกาลที่ 7 ทรงมีพระมหากรุณาธิคุณต่อประเทศชาติและประชาชน ด้านการปกครอง โปรดให้ตั้งสภากรรมการองคมนตรี ทรงตรากฎหมายเพื่อควบคุมการค้าขายที่เป็นสาธารณูปโภคและการเงิน ระบบเทศบาล ด้านการศาสนา การศึกษา ประเพณีและวัฒนธรรมนั้น พระองค์โปรดให้สร้างหอพระสมุด ทรงปฏิรูปการศึกษาระดับมหาวิทยาลัย นอกจากนี้ มีการปรับปรุงการศึกษาจนยกระดับมาตรฐานถึงปริญญาตรี ทรงตั้งราชบัณฑิตยสภา โปรดให้จัดพิมพ์พระไตรปิฎกฉบับพิมพ์อักษรไทยสมบูรณ์ ชื่อว่า “พระไตรปิฎกสยามรัฐ” เป็นต้น</p><p>พระองค์ทรงเป็นพระมหากษัตริย์ภายใต้ระบอบการประชาธิปไตยของไทยพระองค์แรก ทรงพระกรุณาโปรดเกล้าฯ พระราชทานรัฐธรรมนูญแห่งราชอาณาจักรสยาม พุทธศักราช 2475 ซึ่งเป็นรัฐธรรมนูญถาวร ฉบับแรกของไทย เมื่อวันที่ 10 ธันวาคม พ.ศ. 2475 เพื่อเป็นการเฉลิมพระเกียรติพระองค์ให้เป็นที่ประจักษ์ แก่อนุชนรุ่นหลัง รวมทั้งเป็นการน้อมสำนึกในพระมหากรุณาธิคุณ คณะรัฐมนตรีได้มีมติเห็นชอบให้กำหนดวันที่ 30 พฤษภาคม ของทุกปี ซึ่งเป็นวันคล้ายวันสวรรคตของพระองค์ “วันพระบาทสมเด็จพระปกเกล้าเจ้าอยู่หัว”</p>','contents/covers/49rOjEMX1KoaCwVn5YQ1nF0b6yDZmkXOH5UGsMKo.jpg',NULL,NULL,2,0,0,NULL,NULL,1,1,'2026-07-29 11:47:00','2026-07-31 04:47:28','2026-08-01 12:35:16',NULL),
	 (5,'จิตรกรรมฝาผนังในอุโบสถ วัดจันทบุรี อำเภอเสาไห้ จังหวัดสระบุรี','จตรกรรมฝาผนงในอโบสถ-วดจนทบร-อำเภอเสาไห-จงหวดสระบร','BOOKS_AND_JOURNALS','<p>หนังสือ “จิตรกรรมฝาผนังในพระอุโบสถวัดจันทบุรี อำเภอเสาไห้ จังหวัดสระบุรี” จัดทำขึ้นโดยมีวัตถุประสงค์เพื่อเผยแพร่ความรู้เกี่ยวกับจิตรกรรมฝาผนัง ซึ่งเป็นงานศิลปกรรมที่ทรงคุณค่าทางประวัติศาสตร์และวัฒนธรรม แสดงให้เห็นถึงความเชื่อ วิถีชีวิต และภูมิปัญญาของชุมชนในอดีต<br>&nbsp; &nbsp; การจัดทำหนังสือเล่มนี้เป็นส่วนหนึ่งของการสร้าง “แหล่งเรียนรู้ด้านศิลปวัฒนธรรม” ที่เข้าถึงง่าย เพื่อใช้เป็นสื่อการเรียนรู้สำหรับนักเรียน นักศึกษา และประชาชนทั่วไป โดยเนื้อหาได้มาจากงานวิจัยและการลงพื้นที่เก็บข้อมูลจริง พร้อมภาพประกอบและคำอธิบายที่เข้าใจง่าย สามารถใช้ประกอบการศึกษา ค้นคว้า และเป็นข้อมูล<br>พื้นฐานสำหรับการอนุรักษ์จิตรกรรมฝาผนังในอนาคต<br>&nbsp; &nbsp; สำนักศิลปะและวัฒนธรรม หวังเป็นอย่างยิ่งว่าหนังสือเล่มนี้จะเป็นประโยชน์ต่อการเรียนรู้ และช่วยส่งเสริมให้เกิดความตระหนักรู้ในคุณค่าของศิลปวัฒนธรรมท้องถิ่น เพื่อร่วมกันอนุรักษ์และสืบสานให้คงอยู่ต่อไปอย่างยั่งยืน</p>','contents/covers/KtI0QUMlbChidXVab3WPMoB9l3ZYRbxVV0IIqhWh.png',NULL,NULL,1,0,0,NULL,NULL,1,1,'2026-07-29 11:50:00','2026-07-31 04:50:29','2026-08-01 13:14:56',NULL),
	 (5,'นักเขียนลพบุรี','นกเขยนลพบร','BOOKS_AND_JOURNALS','<p>หนังสือ “นักเขียนลพบุรี” เล่มนี้ ถือกำเนิดขึ้นจากความตั้งใจอันแน่วแน่และแรงบันดาลใจอันยาวนานของผู้ช่วยศาสตราจารย์ประทีป เหมือนนิล ซึ่งเป็นผู้แต่งและบรรณาธิการ ท่านได้แสดงความสนใจและสนุกกับการรวบรวมชีวิตและผลงานของนักเขียนไทยร่วมสมัยมาเป็นเวลานานหลายสิบปี เมื่อท่านได้พบเห็นนักเขียนผู้ใด<br>ที่มีความเกี่ยวเนื่องกับจังหวัดลพบุรีก็มักจะเกิดความตื่นเต้นยินดีเสมอ จนกระทั่งเห็นว่าน่าจะจัดทำเป็นหนังสือ “นักเขียนลพบุรี” ขึ้นมาโดยเฉพาะ<br>สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี มีความยินดีเป็นอย่างยิ่งที่ได้มีโอกาสสนับสนุนการจัดพิมพ์และเผยแพร่หนังสือเล่มนี้ อันเป็นไปตามเจตนารมณ์ในการส่งเสริมและสืบสานงานด้านศิลปะและวัฒนธรรมไทย หนังสือ “นักเขียนลพบุรี” นี้ ได้รวบรวมและนำเสนอเรื่องราวของผู้ประพันธ์ที่มีผลงานเป็นที่รู้จักอย่างกว้างขวาง ซึ่งครอบคลุมทั้งผู้ที่มีถิ่นกำเนิดในจังหวัดลพบุรี หรือมีชีวิตบางช่วงเข้ามาเกี่ยวข้องกับจังหวัดลพบุรี ไม่ว่าจะในช่วงของการศึกษาเล่าเรียนหรือการทำงานต่างๆ โดยมีวัตถุประสงค์เพื่อบันทึกเรื่องราวเหล่านี้ไว้ให้สาธารณชนได้ร่วมกันรับรู้และภาคภูมิใจ ว่าจังหวัดลพบุรีมีบุคคลผู้เปี่ยมด้วยความสามารถและใฝ่ใจในงานประพันธ์อยู่ไม่น้อย<br>ด้วยข้อจำกัดด้านเวลาในการเรียบเรียงและการจัดพิมพ์ อาจทำให้มีข้อมูลของนักเขียนลพบุรีที่น่าสนใจอีกหลายท่านที่อาจจะยังตกหล่นไป ทางสำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี จึงหวังเป็นอย่างยิ่งว่าในอนาคตจะมีผู้ดำเนินการจัดทำเพิ่มเติมต่อไป<br>สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี ขอขอบคุณผู้ช่วยศาสตราจารย์ประทีป เหมือนนิล เป็นอย่างสูงที่ได้อุทิศตนสร้างสรรค์ผลงานอันทรงคุณค่าทางวรรณศิลป์นี้ เพื่อเป็นประโยชน์<br>ในการสืบสานศิลปะและวัฒนธรรมไทยสู่ลูกหลานสืบไป</p>','contents/covers/Gg6qFTrj4rQV9Xz888K4yaMKm9wvj2aQwDZ9L9xl.jpg',NULL,NULL,2,0,0,NULL,NULL,1,1,'2026-07-29 11:51:00','2026-07-31 04:51:21','2026-08-01 07:52:17',NULL),
	 (5,'วารสารวัฒนเทพ ปีที่ 5 ฉบับที่ 1 มกราคม 2568 – ธันวาคม 2568','วารสารวฒนเทพ-ปท-5-ฉบบท-1-มกราคม-2568-ธนวาคม-2568','BOOKS_AND_JOURNALS','<p>วารสารวัฒนเทพ ปีที่ 5 ฉบับที่ 1 มกราคม 2568 – ธันวาคม 2568</p>','contents/covers/hMeNHkf30uFikxpWqTLdRh0f2YJYC2XkS9dFfpXe.jpg',NULL,NULL,1,0,1,NULL,NULL,1,1,'2026-07-31 04:52:22','2026-07-31 04:52:22','2026-08-01 09:05:27',NULL),
	 (5,'วารสาร วิทยาลัยครูเทพสตรี ระดับประถม-มัธยม ฉบับที่ 2 ปีการศึกษา 2512','วารสาร-วทยาลยครเทพสตร-ระดบประถม-มธยม-ฉบบท-2-ปการศกษา-2512','BOOKS_AND_JOURNALS','<p>&nbsp;วารสาร วิทยาลัยครูเทพสตรี ระดับประถม-มัธยม ฉบับที่ 2 ปีการศึกษา 2512</p>','contents/covers/jsKuyLzvtNTDOfHQNYmBZGS7MmDDLzlfh724Q5F6.jpg',NULL,NULL,2,0,0,NULL,NULL,1,1,'2026-07-29 11:53:00','2026-07-31 04:53:17','2026-08-01 07:51:51',NULL),
	 (7,'จดหมายข่าวสำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี','จดหมายขาวสำนกศลปะและวฒนธรรม-มหาวทยาลยราชภฏเทพสตร','NEWSLETTER','ประจำเดือน มีนามคม-เมษายน 2566<p><br>จดหมายข่าวสำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี&nbsp;</p>','contents/covers/CunERljljl82LCs9ab48uNrsr8mTZ6lYeOIKYC3u.jpg','doc_1785578138_6a6dc29a881d0.pdf',NULL,1,1,1,NULL,NULL,1,1,'2026-07-29 09:51:00','2026-08-01 09:55:38','2026-08-01 10:29:50',NULL),
	 (7,'จดหมายข่าวสำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี ประจำเดือน เมษายน-มิถุนายน 2566','จดหมายขาวสำนกศลปะและวฒนธรรม-มหาวทยาลยราชภฏเทพสตร-ประจำเดอน-เมษายน-มถนายน-2566','NEWS','<h1>ประจำเดือน เมษายน-มิถุนายน 2566</h1><p><br>จดหมายข่าวสำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี&nbsp;</p>','contents/covers/GzNE5VXX9DuMPMdKKT6r8SRaQvmXtVTY1IkOg9IQ.jpg','doc_1785584970_6a6ddd4a9958c.pdf',NULL,0,0,0,NULL,NULL,1,1,'2026-07-29 11:47:00','2026-08-01 11:49:30','2026-08-01 11:56:20',NULL),
