INSERT INTO enterprise_cms.pages (title,slug,body,secure_pdf_path,view_count,is_active,meta_title,meta_description,deleted_at,created_at,updated_at) VALUES
	 ('คู่มือประชาชน Citizen Service Manuals','คมอประชาชน-citizen-service-manuals','<p>ประกาศมหาวิทยาลัยราชภัฏเทพสตรี เรื่อง ผลการประกวดคำขวัญ "รณรงค์งดเหล้าเข้่าพรรษา"</p>','secure_docs/page_doc_1785598134_6a6e10b672428.pdf',1,1,NULL,NULL,NULL,'2026-08-01 15:27:31','2026-08-01 15:43:25'),
	 ('ประวัติความเป็นมา','history','<p>สืบเนื่องจากคณะรัฐมนตรีมีมติเมื่อวันที่ 1 พฤษภาคม และ 28 สิงหาคม 2527 เห็นชอบในหลักการแผน พัฒนาการอนุรักษ์สิ่งแวดล้อมศิลปกรรม โดยเจตนารมณ์ของแผนเน้นการพัฒนาวิธีการอนุรักษ์สิ่งแวดล้อม ศิลปกรรมให้เป็นระบบ โดย * ให้มีการศึกษาอบรมและประชาสัมพันธ์แก่ประชาชนให้มีความรู้ความเข้าใจ เพื่อเป็นการป้องกันที่ต้นเหตุ * ให้มีหน่วยงานดูแลและตรวจสอบเพื่อป้องกันมิให้เกิดปัญหาลุกลามเกินกว่าจะแก้ไขได้ * ให้มีมาตรการควบคุมการใช้พื้นที่ให้เป็นไปตามกฎหมาย เพื่อให้การพัฒนาเป็นตามหลักการที่ถูกต้องเหมาะสมและประสานประโยชน์แก่ท้องถิ่นและประเทศชาติโดยส่วนรวม</p><p>ในท้องถิ่นนอกจากจะมีมรดกทางวัฒนธรรมแล้ว ยังมีแหล่งวัฒนธรรมอันควรอนุรักษ์ ซึ่งมีแนวทางอนุรักษ์และดำเนินการในลักษณะเดียวกัน คือ การคำนึงถึงสิ่งแวดล้อมธรรมชาติและสิ่งแวดล้อมศิลปกรรม ซึ่งสอดคล้องกับสาระในแผนพัฒนาเศรษฐกิจและสังคมแห่งชาติ ฉบับที่ 6 2532-2534 ด้านทรัพยากรธรรมชาติและสิ่งแวดล้อม ที่เสนอให้มีการปรับปรุงองค์กร ระดับทางด้านสิ่งแวดล้อมศิลปกรรมที่มีอยู่แล้วในทุกจังหวัดให้ครอบคลุมสิ่งแวดล้อมธรรมชาติ และต่อมาในปี พ.ศ.2545 รัฐบาลได้มีการพัฒนาระบบราชการ ที่มุ่งเน้นให้มีการบริหารจัดการอย่างบูรณาการ ซึ่งการบริหารการจัดการในเรื่องสิ่งแวดล้อมธรรมชาติและสิ่งแวดล้อมศิลปกรรม เป็นเรื่องที่มีความสัมพันธ์และมีผลกระทบซึ่งกันและกัน</p><p>ด้วยเหตุนี้ (เมื่อวันที่ 26 พฤศจิกายน 2544 วันที่ 30 มกราคม และ 11 กุมภาพันธ์ 2546 ตามลำดับ) สำนักงานนโยบายและแผนทรัพยากรธรรมชาติและสิ่งแวดล้อม จึงเสนอให้คณะอนุกรรมการอนุรักษ์สิ่งแวดล้อมธรรมชาติและศิลปกรรม ซึ่งเป็นคณะอนุกรรมภายใต้คณะกรรมการสิ่งแวดล้อมแห่งชาติ พิจารณาให้ความเห็นชอบต่อการ เพิ่มบทบาทของหน่วยอนุรักษ์ฯ หน่วยอนุรักษ์สิ่งแวดล้อมธรรมชาติและศิลปกรรมท้องถิ่น (Local Units for Conservation of Natural and Cultural Environment: LUCNCE) โดยมีบทบาทหน้าที่ในการดำเนินงานด้านอนุรักษ์สิ่งแวดล้อมธรรมชาติ ความคู่กันไปการอนุรักษ์สิ่งแวดล้อมศิลปกรรม</p><p>ดังนั้น จึงมีการยกระดับจากหน่วยอนุรักษ์สิ่งแวดล้อมศิลปกรรม เป็น หน่วยอนุรักษ์สิ่งแวดล้อมธรรมชาติและศิลปกรรมท้องถิ่น ในพื้นที่ 75 จังหวัด (ยกเว้น กรุงเทพมหานคร) ซึ่งตั้งอยู่ในมหาวิทยาลัยราชภัฏ 30 แห่ง โรงเรียน 42 แห่ง และสถาบันการพลศึกษา 3 แห่ง โดยมีวัตถุประสงค์ ให้เป็นหน่วยงานในท้องถิ่นที่ช่วยเสริมสร้างความรู้ ความเข้าใจถึงความสำคัญของสิ่งแวดล้อมธรรมชาติและศิลปกรรมให้แก่ประชาชนในท้องถิ่น นอกจากนี้ หน่วยอนุรักษ์ฯ ยังทำหน้าที่อบรมและประชาสัมพันธ์ ด้านการอนุรักษ์สิ่งแวดล้อมธรรมชาติและศิลปกรรม และเป็นหน่วยตรวจสอบดูแลป้องกันปัญหาสิ่งแวดล้อมธรรมชาติและศิลปกรรมที่ต้นเหตุ</p>',NULL,1,1,NULL,NULL,NULL,'2026-08-01 15:48:33','2026-08-01 15:48:35');
